[{"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/.gitattributes", "path": ".gitattributes", "quote": "Shell scripts must keep LF endings on all platforms", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/.gitattributes"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/.pre-commit-config.yaml", "path": ".pre-commit-config.yaml", "quote": "name: namespace check (no hardcoded onnx namespace)", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/.pre-commit-config.yaml"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/CLAUDE.md", "path": "CLAUDE.md", "quote": "All Python files require `from __future__ import annotations`", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/CLAUDE.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/CONTRIBUTING.md", "path": "CONTRIBUTING.md", "quote": "When adding or renaming helper functions in legacy schema files (`old.cc`), prefer explicit opset-based names over numeric suffixes. This keeps intent clear and avoids ambiguity.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/CONTRIBUTING.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/.github/instructions/onnx-defs.instructions.md", "path": ".github/instructions/onnx-defs.instructions.md", "quote": "- **New Python files** need `from __future__ import annotations` and the standard copyright header (`# Copyright (c) ONNX Project Contributors` + `# SPDX-License-Identifier: Apache-2.0`).", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/.github/instructions/onnx-defs.instructions.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/.claude/instructions/add-op.md", "path": ".claude/instructions/add-op.md", "quote": "Schema definition lives in `onnx/defs/<domain>/defs.cc`; register in `onnx/defs/operator_sets.h`.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/.claude/instructions/add-op.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/.claude/instructions/add-shape-inference.md", "path": ".claude/instructions/add-shape-inference.md", "quote": "Always check `hasNInputShapes(ctx, n)` before accessing shapes and `has_dim_value()` before reading dim values.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/.claude/instructions/add-shape-inference.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/.claude/instructions/add-function-body.md", "path": ".claude/instructions/add-function-body.md", "quote": "For context-dependent builders, always finalize with `schema.BuildFunction(functionProto)` and `return true`.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/.claude/instructions/add-function-body.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/.agents/skills/add-op/SKILL.md", "path": ".agents/skills/add-op/SKILL.md", "quote": "Define shape inference functions and function body builders as **separate named functions** rather than inline lambdas within `ONNX_OPERATOR_SET_SCHEMA`.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/.agents/skills/add-op/SKILL.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/.agents/skills/add-shape-inference/SKILL.md", "path": ".agents/skills/add-shape-inference/SKILL.md", "quote": "Define inference functions as **separate named functions** rather than inline lambdas.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/.agents/skills/add-shape-inference/SKILL.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/.agents/skills/add-function-body/SKILL.md", "path": ".agents/skills/add-function-body/SKILL.md", "quote": "- Variable names are local intermediates; input/output names must match the schema's declared names.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/.agents/skills/add-function-body/SKILL.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/.agents/skills/onnxtxt/SKILL.md", "path": ".agents/skills/onnxtxt/SKILL.md", "quote": "Inputs/outputs of a function body must match the names declared in the schema's `.Input(...)` / `.Output(...)`.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/.agents/skills/onnxtxt/SKILL.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/.agents/skills/add-op/references/node-test-pattern.md", "path": ".agents/skills/add-op/references/node-test-pattern.md", "quote": "Each `export*` static method becomes a separate test case.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/.agents/skills/add-op/references/node-test-pattern.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/pyproject.toml", "path": "pyproject.toml", "quote": "Disallow all relative imports.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/pyproject.toml"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/.lintrunner.toml", "path": ".lintrunner.toml", "quote": "Do not hardcode onnx's namespace in the c++ source code", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/.lintrunner.toml"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/tools/check_namespace.py", "path": "tools/check_namespace.py", "quote": "Check that C++ files do not hardcode the onnx namespace.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/tools/check_namespace.py"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/docs/AddNewOp.md", "path": "docs/AddNewOp.md", "quote": "Shape inference functions must be accompanied by unit tests ([onnx/test/shape_inference_test.py](/onnx/test/shape_inference_test.py)).", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/docs/AddNewOp.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/docs/AddFunctionBody.md", "path": "docs/AddFunctionBody.md", "quote": "- **Input/output names** must match the schema's declared `.Input()` and `.Output()` names exactly", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/docs/AddFunctionBody.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/docs/ShapeInference.md", "path": "docs/ShapeInference.md", "quote": "Use `checkInputRank` for inputs that must have a fixed rank.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/docs/ShapeInference.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/docs/OnnxBackendTest.md", "path": "docs/OnnxBackendTest.md", "quote": "each `expect(...)` statement in the code corresponds to one test case.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/docs/OnnxBackendTest.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/docs/VersionConverter.md", "path": "docs/VersionConverter.md", "quote": "Please ensure that all adapters convert from opset version i to i + 1
or i - 1, i.e. from Version 6 to Version 5 or vice versa, even if the 2 versions
being converted between are Version 1 and Version 6.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/docs/VersionConverter.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/docs/Versioning.md", "path": "docs/Versioning.md", "quote": "Required fields MUST always be marked with the comment:", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/docs/Versioning.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/docs/ExternalDataSecurity.md", "path": "docs/ExternalDataSecurity.md", "quote": "All POSIX fds are opened with `O_CLOEXEC`. All platforms return a CRT file descriptor.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/docs/ExternalDataSecurity.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/docs/AssuranceCase.md", "path": "docs/AssuranceCase.md", "quote": "No shell execution in ONNX Core; no system()/exec() usage", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/docs/AssuranceCase.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/docs/OpConventions.md", "path": "docs/OpConventions.md", "quote": "All attribute names should be lower case and use underscores when it helps with readability", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/docs/OpConventions.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/docs/DefineDifferentiability.md", "path": "docs/DefineDifferentiability.md", "quote": "The ONNX operator schema for each operator includes a differentiability tag for each input and output.", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/docs/DefineDifferentiability.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/onnx/fuzz/README.md", "path": "onnx/fuzz/README.md", "quote": "`TestOneInput` is the [required entry-point name](https://github.com/google/atheris#usage)", "url": "https://github.com/onnx/onnx/blob/57bb876250ecc07623a744512d94b44221fb3ed8/onnx/fuzz/README.md"}, {"artifact_path": "guideline-files/onnx/onnx/57bb876250ecc07623a744512d94b44221fb3ed8/onnx/helper.py", "path": "onnx/helper.py", "quote": "# This is a copy of the documented version in https://github.com/onnx/onnx/blob/main/docs/Versioning.md#released-versions
